<?php
declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Database.php';require_once __DIR__.'/../app/Auth.php';require_once __DIR__.'/../app/UserStorage.php';require_once __DIR__.'/../app/WorkspaceService.php';require_once __DIR__.'/../app/ActionLog.php';
try{$u=(new Auth($config))->requireUser();if((int)$u['id']<1)throw new RuntimeException('Staging exige conta permanente.');$pdo=Database::connection($config);$in=request_json();$op=(string)($in['op']??'list');$home=UserStorage::home($config,(int)$u['id']);$ws=new WorkspaceService(array_merge($config,['workspace'=>$home]));if($op==='create'){$files=(array)($in['files']??[]);if(!$files)throw new InvalidArgumentException('Nenhum arquivo na proposta.');$id=bin2hex(random_bytes(16));$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO staging_proposals(id,user_id,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 DAY))');$s->execute([$id,(int)$u['id']]);foreach($files as $f){$path=(string)($f['path']??'');$operation=(string)($f['operation']??'create');if(!in_array($operation,['create','replace','delete'],true))throw new InvalidArgumentException('Operação de staging inválida.');if($path==='')throw new InvalidArgumentException('Caminho vazio na proposta.');$abs=$ws->safe($path,$operation==='replace'||$operation==='delete');if($operation==='create'&&is_file($abs))throw new InvalidArgumentException('Arquivo já existe para operação create.');$content=$f['content']??null;if($operation!=='delete'&&!is_string($content))throw new InvalidArgumentException('Conteúdo inválido na proposta.');if(is_string($content)&&strlen($content)>($config['limits']['max_file_bytes']??2097152))throw new InvalidArgumentException('Arquivo da proposta excede o limite.');$hash=is_file($abs)?hash_file('sha256',$abs):null;$s=$pdo->prepare('INSERT INTO staging_files(proposal_id,relative_path,operation,content,original_hash) VALUES(?,?,?,?,?)');$s->execute([$id,$path,$operation,$content,$hash]);}$pdo->commit();ActionLog::write($config,$u,'staging.create',$id,['files'=>count($files)]);json_response(['ok'=>true,'id'=>$id]);}if($op==='list'){$s=$pdo->prepare('SELECT * FROM staging_proposals WHERE user_id=? ORDER BY created_at DESC');$s->execute([(int)$u['id']]);json_response(['ok'=>true,'items'=>$s->fetchAll()]);}$id=(string)($in['id']??'');$s=$pdo->prepare('SELECT * FROM staging_proposals WHERE id=? AND user_id=?');$s->execute([$id,(int)$u['id']]);$proposal=$s->fetch();if(!$proposal)throw new RuntimeException('Proposta não encontrada.');if(!empty($proposal['expires_at'])&&strtotime((string)$proposal['expires_at'])<time()&&$proposal['status']==='pending')throw new RuntimeException('Proposta expirada.');if($op==='files'){$s=$pdo->prepare('SELECT * FROM staging_files WHERE proposal_id=?');$s->execute([$id]);json_response(['ok'=>true,'proposal'=>$proposal,'files'=>$s->fetchAll()]);}if($op==='reject'){$s=$pdo->prepare('UPDATE staging_proposals SET status="rejected" WHERE id=? AND status IN ("pending","approved")');$s->execute([$id]);ActionLog::write($config,$u,'staging.reject',$id);json_response(['ok'=>true]);}if($op==='approve'){$s=$pdo->prepare('UPDATE staging_proposals SET status="approved" WHERE id=? AND status="pending"');$s->execute([$id]);ActionLog::write($config,$u,'staging.approve',$id);json_response(['ok'=>true]);}if($op==='apply'){if($proposal['status']!=='approved')throw new RuntimeException('A proposta precisa ser aprovada antes da aplicação.');$s=$pdo->prepare('SELECT * FROM staging_files WHERE proposal_id=?');$s->execute([$id]);$files=$s->fetchAll();$resolved=[];foreach($files as $f){$abs=$ws->safe((string)$f['relative_path'],(string)$f['operation']!=='create');if($f['original_hash']!==null&&is_file($abs)&&hash_file('sha256',$abs)!==$f['original_hash'])throw new RuntimeException('Arquivo alterado externamente: '.$f['relative_path']);$resolved[]=['row'=>$f,'abs'=>$abs];}$backups=[];foreach($resolved as $item){$f=$item['row'];$abs=$item['abs'];if(is_file($abs)){$backup=$abs.'.staging.'.date('YmdHis').'.bak';if(!copy($abs,$backup))throw new RuntimeException('Falha ao criar backup.');$backups[]=$backup;}if($f['operation']==='delete'){if(is_file($abs)&&!unlink($abs))throw new RuntimeException('Falha ao excluir arquivo.');}else{if(!is_dir(dirname($abs))&&!mkdir(dirname($abs),0775,true))throw new RuntimeException('Falha ao criar pasta.');if(file_put_contents($abs,(string)$f['content'],LOCK_EX)===false)throw new RuntimeException('Falha ao gravar arquivo.');}}$s=$pdo->prepare('UPDATE staging_proposals SET status="applied" WHERE id=? AND status="approved"');$s->execute([$id]);ActionLog::write($config,$u,'staging.apply',$id,['files'=>count($files),'backups'=>$backups]);json_response(['ok'=>true,'backups'=>$backups]);}throw new InvalidArgumentException('Operação inválida.');}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
?>
